/// histories.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's email address for authentication. Must be unique across all
  /// members.
  email String

  /// Hashed password for secure authentication. Never stored in plain text.
  password_hash String

  /// User's display name (1-100 characters). Visible in the user's profile.
  display_name String

  /// Account creation timestamp. Immutable after registration.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp. Updated on profile changes.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for account deletion. When set, account is
  /// considered deleted and all owned data is permanently removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  memberSessions todo_app_member_sessions[]
  passwordResets todo_app_member_password_resets[]
  emailVerifications todo_app_member_email_verifications[]
  todos todo_app_todos[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([deleted_at])
}

