  TestValidator.equals("member ID preserved", refreshResult.id, loginResult.id);
  TestValidator.equals(
    "email preserved",
    refreshResult.email,
    loginResult.email,
  );
  TestValidator.equals(
    "display name preserved",
    refreshResult.displayName,
    loginResult.displayName,
  );
}

