@Controller("/todoApp/member/sessions")
export class TodoappMemberSessionsController {
  /**
   * Retrieve a filtered and paginated list of authentication sessions for the authenticated member account.
   *
   * This operation provides comprehensive session management capabilities by querying the `todo_app_member_sessions` table. Members can review their login history across all devices and locations, viewing details including the client IP address (`ip`), login page URL (`href`), referrer information (`referrer`), session creation timestamp (`created_at`), and expiration timestamp (`expired_at`).
   *
   * Supports advanced filtering by date ranges on `created_at` and `expired_at` columns, IP address pattern matching, and session status filtering (active vs expired). Sessions are sorted by `created_at` in descending order (newest first) by default, with cursor-based pagination for efficient navigation through large result sets.
   *
   * Security considerations:
   * - Only the authenticated member can access their own sessions via `todo_app_member_id` isolation
   * - Session data includes IP addresses and login timestamps for security auditing purposes
   * - Expired sessions remain visible for historical review until account deletion
   * - Member account soft deletion (via `deleted_at` on `todo_app_members`) cascades to permanently remove all owned sessions
   * - Account deletion requires explicit confirmation before processing
   *
   * @param connection
   * @param body Search criteria and pagination parameters for session list retrieval
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query todo_app_member_sessions table filtered by authenticated member's ID. Apply search filters from request body: date range (created_at, expired_at), IP address pattern matching, session status (active vs expired). Implement cursor-based pagination with configurable page size. Sort by created_at descending (newest first). Enforce member isolation - only return sessions where todo_app_member_id matches authenticated user. Join with todo_app_members to verify account is not deleted. Return session summary with id, ip, href, referrer, created_at, expired_at fields.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: ITodoAppMemberSession.IRequest,
  ): Promise<IPageITodoAppMemberSession.ISummary> {
    try {
      return await patchTodoAppMemberSessions({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific authentication session owned by the authenticated member.
   *
   * This endpoint provides complete session metadata including the client IP address, login URL (href), referrer information, creation timestamp, and expiration timestamp. Session records serve as an audit trail for member authentication events and are used for security monitoring and session management purposes.
   *
   * **Authorization**: Only the member who owns this session can access it. Members cannot view sessions belonging to other users. This enforces strict data isolation and privacy boundaries.
   *
   * **Session Context**: Each session represents a single login event for a member account. Members can have multiple concurrent sessions active simultaneously, enabling multi-device access. Sessions are tracked with connection metadata for security auditing.
   *
   * **Related Operations**:
   * - `PATCH /sessions` - List all sessions belonging to the authenticated member with pagination and filtering
   * - `DELETE /sessions/{sessionId}` - Revoke a specific session (logout from a specific device)
   *
   * **Session Expiration**: Sessions have an `expired_at` timestamp that determines when they become invalid for authentication. Expired sessions remain in the audit trail but cannot be used for authentication purposes.
   *
   * @param connection
   * @param sessionId Unique identifier of the session to retrieve (UUID format)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query the todo_app_member_sessions table by session ID (UUID primary key).
   *
   * **Authorization Flow**:
   * 1. Extract authenticated member ID from JWT token in Authorization header
   * 2. Query todo_app_member_sessions WHERE id = sessionId AND todo_app_member_id = authenticated_member_id
   * 3. If no matching session found, return 404 Not Found
   * 4. If session exists but belongs to different member, return 403 Forbidden
   *
   * **Database Query**:
   * ```sql
   * SELECT id, todo_app_member_id, ip, href, referrer, created_at, expired_at
   * FROM todo_app_member_sessions
   * WHERE id = $1 AND todo_app_member_id = $2
   * ```
   *
   * **Response Construction**:
   * - Map database row to ITodoAppMemberSession DTO
   * - Include all session fields: id, memberId, ip, href, referrer, createdAt, expiredAt
   * - Return 200 OK with session details
   *
   * **Error Handling**:
   * - 401 Unauthorized: No valid authentication token provided
   * - 403 Forbidden: Session exists but belongs to different member
   * - 404 Not Found: Session ID not found or already deleted
   *
   * **Performance Considerations**:
   * - Use indexed lookup on id primary key
   * - Filter by todo_app_member_id for data isolation
   * - Single row retrieval, O(1) complexity
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":sessionId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("sessionId")
